@@ -0,0 +1,13 @@
+import { createEventCard } from './event-card.js';
+
+export function sortByStart(items, getStart = (item) => item.startsAt) {
+  return items
+    .map((item, index) => ({ item, index, time: new Date(getStart(item)).getTime() }))
+    .sort((a, b) => a.time - b.time || a.index - b.index)
+    .map(({ item }) => item);
+}
+
+export function buildAgenda(events) {
+  const entries = events.map((event) => ({ card: createEventCard(event), startsAt: event.startsAt }));
+  return sortByStart(entries).map(({ card }) => card);
+}

